    // Cloud sync, support helper, patch helper
    "Endcord comes with a cloud integration that adds goodies like settings sync across devices. It": "Endcord, cihazlar arasında ayar senkronizasyonu gibi özellikler ekleyen bir bulut entegrasyonuyla gelir. Bu entegrasyon",
    "respects your privacy": "gizliliğine saygı duyar",
    ", and the": ", ve",
    "source code": "kaynak kodu",
    "is AGPL 3.0 licensed so you can host it yourself.": "AGPL 3.0 lisanslıdır, böylece kendin barındırabilirsin.",
    "This setting controls how settings move between": "Bu ayar, ayarların",
    "this device": "bu cihaz",
    "and the cloud. You can let changes flow both ways, or choose one place to be the main source of truth.": "ile bulut arasında nasıl taşınacağını belirler. Değişiklikleri iki yönlü akıtabilir ya da tek bir yeri asıl kaynak seçebilirsin.",
    "This will replace your current settings with the ones saved in the cloud. Be careful!": "Bu, şu anki ayarlarını buluttakilerle değiştirir. Dikkatli ol!",
