    // Friendly error messages and plugin conflict warning
    "{name} and {others} don't mix": "{name} ile {others} anlaşamıyor",
    "They change the same part of Discord, so one of them would stop working. Turn off {others} and use {name} instead?": "İkisi de Discord'un aynı kısmını değiştiriyor, bu yüzden biri çalışmayı bırakır. {others} kapatılıp yerine {name} kullanılsın mı?",
