    "This little part of Endcord tripped over itself. Everything else still works, and the details below help us fix it.": "Endcord'un bu küçük parçası tökezledi. Geri kalan her şey çalışıyor, aşağıdaki ayrıntılar da düzeltmemize yardım eder.",
    "The {tab} tab tripped over itself (｡•́︿•̀｡) If it keeps happening, reinstalling Endcord with the installer fixes it.": "{tab} sekmesi tökezledi (｡•́︿•̀｡) Tekrarlarsa Endcord'u installer ile yeniden kurmak düzeltir.",
    "This plugin's info panel tripped over itself, but its settings still work.": "Bu plugin'in bilgi paneli tökezledi ama ayarları hâlâ çalışıyor.",
    "{name} didn't want to stop :( Restart Discord and it'll be off.": "{name} kapanmak istemedi :( Discord'u yeniden başlatınca kapanmış olacak.",
    "{name} couldn't start this time :( Try turning it on again, or restart Discord.": "{name} bu sefer başlayamadı :( Tekrar açmayı dene ya da Discord'u yeniden başlat.",
    "Some helpers this plugin needs couldn't start :( {list}": "Bu plugin'in ihtiyaç duyduğu bazı yardımcılar başlayamadı :( {list}",
    "Couldn't check for updates right now :( Check your internet and try again in a bit.": "Şu an güncellemeler kontrol edilemedi :( İnternetini kontrol edip biraz sonra tekrar dene.",
    "Something unexpected got in the way, sorry about that.": "Beklenmedik bir şey araya girdi, kusura bakma.",
    "Couldn't load this right now :(": "Şu an yüklenemedi :(",
    "The update didn't go through :( Grab the latest installer and reinstall, that always does the trick!": "Güncelleme olmadı :( En son installer'ı indirip yeniden kur, her zaman işe yarar!",
    "Couldn't import those settings :( {error}": "Bu ayarlar içe aktarılamadı :( {error}",
    "That invite doesn't work anymore :(": "Bu davet artık çalışmıyor :(",
    "Hmm, that doesn't look quite right. Mind checking it?": "Hmm, bu pek doğru görünmüyor. Bir kontrol eder misin?",
    "Whoops, Discord tripped!": "Hoppala, Discord tökezledi!",
    "Discord tripped twice in a row, so Endcord is letting it rest this time. Press Ctrl+R if anything looks stuck.": "Discord üst üste iki kez tökezledi, bu yüzden Endcord bu sefer onu dinlendiriyor. Bir şey takılı kalırsa Ctrl+R'ye bas.",
    "Discord just tripped, but good news: a fresh Endcord update might fix it! Want to update now?": "Discord tökezledi ama iyi haber: yeni bir Endcord güncellemesi bunu düzeltebilir! Şimdi güncellensin mi?",
