    "Modify Features": "Özellikleri Değiştir",
    "Discord is known to punish users of scripts or plugins that modify the completion of Quests. Modifying the completion of Quests is against Discord's": "Discord'un, görevlerin tamamlanmasını değiştiren betik ya da plugin kullananları cezalandırdığı biliniyor. Görev tamamlamayı değiştirmek Discord'un şuna aykırı:",
    "Terms of Service": "Hizmet Koşulları",
    "The punishment consists of a temporary or permanent loss of access to Quests and their rewards.": "Ceza, görevlere ve ödüllerine erişimin geçici ya da kalıcı olarak kaybedilmesidir.",
    "The punishment also consists of an account standing violation which lasts 2 years per violation.": "Ceza ayrıca her ihlal için 2 yıl süren bir hesap durumu ihlali de içerir.",
    "Due to the various methods Discord uses to track users, there's no way to realistically evade detection. If you proceed, understand that Discord likely will detect your use at some point.": "Discord'un kullanıcıları izlemek için kullandığı çeşitli yöntemler yüzünden tespit edilmekten gerçekçi olarak kaçınmanın yolu yok. Devam edersen, Discord'un bir noktada büyük ihtimalle bunu tespit edeceğini bil.",
    "Use the following toggle to access potentially dangerous settings at your own risk.": "Potansiyel olarak tehlikeli ayarlara riski sana ait olmak üzere erişmek için aşağıdaki anahtarı kullan.",
    "Hide Non Auto-Completable Quests:": "Otomatik tamamlanamayan görevleri gizle:",
    "Accelerate Video Quest auto-completion:": "Video görevlerinin otomatik tamamlanmasını hızlandır:",
