    "Discord has implemented a Quest Ban system which will temporarily or permanently limit your access to completing Quests and claiming their rewards if you are found to be completing them through unofficial means. Modifying the completion of Quests is against their": "Discord, görevleri resmi olmayan yollarla tamamladığın tespit edilirse görevleri tamamlama ve ödülleri alma erişimini geçici ya da kalıcı olarak kısıtlayan bir Görev Yasağı sistemi getirdi. Görev tamamlamayı değiştirmek şuna aykırı:",
    "The punishment appears limited to loss of access to Quests and their rewards, but Discord may escalate at any time.": "Ceza şimdilik görevlere ve ödüllerine erişim kaybıyla sınırlı görünüyor, ama Discord bunu her an ağırlaştırabilir.",
    "Due to the various methods Discord uses to track users, there's no way to realistically evade detection. If you proceed, understand that Discord likely will detect it at some point.": "Discord'un kullanıcıları izlemek için kullandığı çeşitli yöntemler yüzünden tespit edilmekten gerçekçi olarak kaçınmanın yolu yok. Devam edersen, Discord'un bir noktada büyük ihtimalle bunu fark edeceğini bil.",
    "Discord has begun punishing users of scripts and plugins that modify the completion of Quests. Modifying the completion of Quests is against their": "Discord, görevlerin tamamlanmasını değiştiren betik ve plugin kullananları cezalandırmaya başladı. Görev tamamlamayı değiştirmek şuna aykırı:",
