    "Blocked Users": "Engellenen Kullanıcılar",
    "Display your currently playing audiobooks as Discord Rich Presence. Requires your AudioBookShelf server URL, username, and password.": "Dinlediğin sesli kitapları Discord zengin durumu olarak göster. AudioBookShelf sunucu URL'ni, kullanıcı adını ve şifreni gerektirir.",
    "Connects to tosu via WebSocket on port 24050. No configuration needed, just make sure tosu is running alongside osu!.": "24050 portundan WebSocket ile tosu'ya bağlanır. Ayar gerekmez, sadece tosu'nun osu! ile birlikte çalıştığından emin ol.",
    "Show what you're currently listening to via stats.fm. Requires your listening history to be public.": "stats.fm üzerinden şu an dinlediğini göster. Dinleme geçmişinin herkese açık olması gerekir.",
    "stats.fm username": "stats.fm kullanıcı adı",
    "Show what you're playing on Jellyfin. To get your API key: open your Jellyfin web UI, press F12 to open Developer Tools, go to the Network tab, look for requests to your server, find the Authorization header (Ctrl+F to search), and You need the part from Token='this'. Your user ID can be found in your profile page URL.": "Jellyfin'de ne izlediğini göster. API anahtarını almak için: Jellyfin web arayüzünü aç, Geliştirici Araçları için F12'ye bas, Ağ sekmesine geç, sunucuna giden istekleri bul, Authorization başlığını ara (Ctrl+F ile) ve Token='bu' kısmını al. Kullanıcı kimliğin profil sayfası URL'sinde bulunur.",
    "User ID from profile URL": "Profil URL'sindeki kullanıcı kimliği",
    "{name} on Jellyfin": "Jellyfin'de {name}",
    "Discord rich presence for Gensokyo Radio. Just enable it and listen!": "Gensokyo Radio için Discord zengin durumu. Aç ve dinle!",
