    "This fix isn't perfect, so you may have to reload the search bar to fix issues.": "Bu düzeltme kusursuz değil, sorun olursa arama çubuğunu yeniden yüklemen gerekebilir.",
    "Discord only allows a max offset of 5000 (this is what causes the magnifying glass error). This means that you can only see precisely 5000 messages into the past, and 5000 messages into the future (when sorting by old). This plugin just jumps to the opposite sorting method to try get around Discord's restriction, but if there is a large search result, and you try to view a message that is unobtainable with both methods of sorting, the plugin will simply show offset 0 (either newest or oldest message depending on the sorting method).": "Discord en fazla 5000 ofsete izin verir (büyüteç hatasının sebebi bu). Yani geçmişe doğru tam 5000 mesaj, eskiye göre sıralarken de geleceğe doğru 5000 mesaj görebilirsin. Bu plugin, Discord'un kısıtlamasını aşmak için ters sıralamaya geçer; ama arama sonucu çok büyükse ve iki sıralamayla da ulaşılamayan bir mesajı görmeye çalışırsan, plugin ofset 0'ı gösterir (sıralamaya göre en yeni ya da en eski mesaj).",
